<?php use yii\helpers\{Html,Url};use yii\widgets\ActiveForm;$this->title='Register';?><main class="loginbox"><section class="loginbrand"><img src="<?=Url::to('@web/assets/sppu/dti-logo.png')?>"><p>Department of Trade and Industry • Caraga</p><h1>Create User Account</h1><span>Full system access</span></section><section class="logincard"><h2>Register</h2><?php $f=ActiveForm::begin();?><?=$f->field($model,'name')?><?=$f->field($model,'email')->input('email')?><?=$f->field($model,'password')->passwordInput()?><?=$f->field($model,'password_confirm')->passwordInput()?><?=Html::submitButton('Create account',['class'=>'btn primary'])?><?php ActiveForm::end();?><?=Html::a('Back to sign in',['login'],['class'=>'btn'])?></section></main>
